// VectorMCPVectorToolsetHandleError converts an error into a tool result with appropriate retry hints.
func VectorMCPVectorToolsetHandleError(toolName tools.Ident, err error) planner.ToolResult {
	result := planner.ToolResult{
		Error: planner.ToolErrorFromError(err),
		Name:  toolName,
	}
	if hint := VectorMCPVectorToolsetRetryHint(toolName, err); hint != nil {
		result.RetryHint = hint
	}
	return result
}

